const input = $json;

function parseMaybeJson(value, fallback = {}) {
  if (value && typeof value === 'object') return value;
  if (typeof value !== 'string') return fallback;
  try {
    return JSON.parse(value);
  } catch {
    return fallback;
  }
}

const executionContext = parseMaybeJson(input.execution_context, {});
const contextPacket = parseMaybeJson(input.context_packet, {});
const state = contextPacket.state || {};
const stateUpdate = parseMaybeJson(input.state_update, executionContext.state_update || {});
const decision = parseMaybeJson(input.decision, {});

function firstValue(...values) {
  for (const value of values) {
    if (value !== undefined && value !== null && String(value).trim() !== "") return value;
  }
  return null;
}

function hasExplicitStateField(key) {
  return Object.prototype.hasOwnProperty.call(stateUpdate, key);
}

const hasExplicitNewSlot = (
  hasExplicitStateField("booking_date")
    ? !!(stateUpdate.booking_date && String(stateUpdate.booking_date).trim())
    : !!firstValue(input.booking_date)
) && (
  hasExplicitStateField("booking_time")
    ? !!(stateUpdate.booking_time && String(stateUpdate.booking_time).trim())
    : !!firstValue(input.booking_time)
);

const genericRescheduleRequest =
  decision.reason === "user_requested_reschedule" ||
  stateUpdate.next_goal === "collect_new_slot" ||
  stateUpdate.intent_last === "reschedule_booking_requested";

const shouldListNewSlots = genericRescheduleRequest && !hasExplicitNewSlot;

const leadId =
  input.lead_id ||
  executionContext.lead_id ||
  contextPacket.lead?.id ||
  null;

const phone =
  input.phone ||
  executionContext.phone ||
  contextPacket.lead?.phone ||
  null;

const channel =
  input.channel ||
  executionContext.channel ||
  contextPacket.lead?.channel ||
  "whatsapp";

if (!leadId) {
  throw new Error("Missing lead_id in reschedule_booking");
}

return [{
  ...input,

  lead_id: leadId,
  phone,
  channel,

  calendar_id:
    input.calendar_id ||
    executionContext.calendar_id ||
    state.calendar_id ||
    "0806113eec0244bd64e4ef9658d05e6238f5e9e90c33621efb2fbb52150ee3eb@group.calendar.google.com",

  agent_id:
    input.agent_id ||
    executionContext.agent_id ||
    contextPacket.routing?.agent_id ||
    contextPacket.agent?.id ||
    null,

  booking_date: shouldListNewSlots
    ? null
    : firstValue(input.booking_date, stateUpdate.booking_date, executionContext.booking_date, state.booking_date),

  booking_time: shouldListNewSlots
    ? null
    : firstValue(input.booking_time, stateUpdate.booking_time, executionContext.booking_time, state.booking_time),

  slot_id: shouldListNewSlots
    ? null
    : firstValue(input.slot_id, stateUpdate.slot_id, executionContext.slot_id, state.slot_id),

  duration_minutes: Number(
    input.duration_minutes ||
    executionContext.duration_minutes ||
    state.duration_minutes ||
    120
  ),

  service_interest:
    input.service_interest ||
    executionContext.service_interest ||
    state.service_interest ||
    null,

  vehicle_type:
    input.vehicle_type ||
    executionContext.vehicle_type ||
    state.vehicle_type ||
    null,

  district:
    input.district ||
    executionContext.district ||
    state.district ||
    null,

  availability_window:
    input.availability_window ||
    executionContext.availability_window ||
    state.availability_window ||
    "this_week",

  availability_label:
    input.availability_label ||
    stateUpdate.availability_label ||
    executionContext.availability_label ||
    state.availability_label ||
    "los proximos dias",

  days_ahead: Number(
    input.days_ahead ||
    executionContext.days_ahead ||
    state.days_ahead ||
    7
  ),

  start_offset_days: Number(
    input.start_offset_days ||
    executionContext.start_offset_days ||
    state.start_offset_days ||
    0
  ),

  max_slots: Number(
    input.max_slots ||
    executionContext.max_slots ||
    state.max_slots ||
    3
  ),

  reschedule_reason:
    input.reschedule_reason ||
    executionContext.reschedule_reason ||
    input.decision?.reason ||
    "user_requested_reschedule",

  execution_context: {
    ...executionContext,
    lead_id: leadId,
    phone,
    channel,
    action: "reschedule_booking"
  },

  context_packet: contextPacket,
  state_update: {
    ...stateUpdate,
    booking_date: shouldListNewSlots ? null : stateUpdate.booking_date,
    booking_time: shouldListNewSlots ? null : stateUpdate.booking_time,
    slot_id: shouldListNewSlots ? null : stateUpdate.slot_id,
    availability_confirmed: shouldListNewSlots ? false : stateUpdate.availability_confirmed,
    next_goal: shouldListNewSlots ? "collect_selected_slot" : stateUpdate.next_goal,
    last_bot_action: shouldListNewSlots ? "reschedule_booking_in_progress" : stateUpdate.last_bot_action
  },
  decision: input.decision || {},
  execution_meta: input.execution_meta || {},

  notes: [
    ...(input.notes || []),
    "reschedule_input_normalized"
  ]
}];

const original = $("normalize_reschedule_input").first().json;

const activeAppointment = $json.id
  ? {
      id: $json.id,
      event_id: $json.event_id,
      conversation_id: $json.conversation_id,
      start_at: $json.start_at,
      end_at: $json.end_at,
      summary: $json.summary,
      description: $json.description,
      status: $json.status,
      service_address: $json.service_address,
      address_reference: $json.address_reference
    }
  : null;

return [{
  ...original,
  active_appointment: activeAppointment,
  notes: [
    ...(original.notes || []),
    activeAppointment ? "active_appointment_found" : "no_active_appointment_found"
  ]
}];

return [{
  ...$json,
  message_to_send:
    "No encontre una reserva activa para reprogramar. Si quieres, puedo ayudarte a agendar una nueva.",
  db_operations: ["messages", "lead_state"],
  state_update: {
    ...($json.state_update || {}),
    last_bot_action: "reschedule_no_active_appointment",
    next_goal: "offer_booking",
    missing_fields: []
  },
  notes: [
    ...($json.notes || []),
    "reschedule_blocked_no_active_appointment"
  ]
}];

const original = (() => {
  try {
    return $("normalize_reschedule_input").first().json;
  } catch {
    return {};
  }
})();

const slots = Array.isArray($json.slots) ? $json.slots : [];
const availabilityLabel =
  original.availability_label ||
  $json.availability_label ||
  "los proximos dias";

function formatSlot(slot) {
  const start = new Date(slot.slot_start_at);

  const fecha = start.toLocaleDateString("es-CL", {
    timeZone: "America/Santiago",
    weekday: "long",
    day: "2-digit",
    month: "long"
  });

  const hora = start.toLocaleTimeString("es-CL", {
    timeZone: "America/Santiago",
    hour: "2-digit",
    minute: "2-digit"
  });

  return fecha + " a las " + hora;
}

function buildCommonPayload(message, stateUpdate, extraNotes) {
  const decision = {
    ...(original.decision || {}),
    action: "reschedule_booking",
    reason: stateUpdate.last_bot_action || "reschedule_slots_offered",
    source: "reschedule_booking",
    rule_name: "reschedule_booking_slots",
    confidence: 1,
    message,
    state_update: stateUpdate,
    requires_message_builder: false
  };

  return {
    ...original,
    ...$json,
    message_to_send: message,
    message,
    db_operations: ["messages", "lead_state"],
    action: "reschedule_booking",
    outcome: stateUpdate.last_bot_action,
    decision,
    state_update: stateUpdate,
    execution_context: {
      ...(original.execution_context || {}),
      action: "reschedule_booking",
      state_update: stateUpdate,
      idempotency_key: null,
      inbound_message_id: null
    },
    idempotency_key: null,
    inbound_message_id: null,
    execution_result: {
      success: true,
      action: "reschedule_booking",
      outcome: stateUpdate.last_bot_action,
      bot: message,
      message_sent: false,
      state_updated: false,
      db_records_created: []
    },
    notes: [
      ...(original.notes || []),
      ...($json.notes || []),
      ...extraNotes
    ]
  };
}

if (slots.length === 0) {
  const stateUpdate = {
    ...(original.state_update || {}),
    stage: "reschedule",
    intent_last: "reschedule_no_available_slots",
    next_goal: "manual_availability_review",
    last_bot_action: "reschedule_no_slots_found",
    missing_fields: [],
    booking_options: []
  };

  const message =
    "Claro, podemos reprogramar, pero por ahora no encontre horarios disponibles para " +
    availabilityLabel +
    ". Te puedo ayudar a revisar otra alternativa.";

  return [buildCommonPayload(message, stateUpdate, ["reschedule_no_available_slots"])]
}

const lines = slots.map((slot, index) => String(index + 1) + ". " + formatSlot(slot));
const optionNumbers = slots.map((_, index) => index + 1).join(", ");

const stateUpdate = {
  ...(original.state_update || {}),
  stage: "reschedule",
  intent_last: "reschedule_requested",
  next_goal: "collect_selected_slot",
  last_bot_action: "offer_reschedule_slots",
  missing_fields: [],
  booking_date: null,
  booking_time: null,
  slot_id: null,
  availability_confirmed: false,
  booking_options: slots,
  availability_window: original.availability_window || $json.availability_window || "this_week",
  availability_label: availabilityLabel
};

const message =
