  inbound_message_id: null,

  execution_result: {
    ...(data.execution_result || {}),
    success: true,
    action: "reschedule_booking",
    outcome,
    bot: finalMessage,
    message_sent: false,
    state_updated: false,
    db_records_created: []
  },

  notes: [
    ...(data.notes || []),
    `reschedule_booking_outcome_${outcome}`
  ]
}];

