    reason: stateUpdate.last_bot_action || "reschedule_slots_offered",
    source: "reschedule_booking",
    rule_name: "reschedule_booking_slots",
    confidence: 1,
    message,
    state_update: stateUpdate,
    requires_message_builder: false
  };

  return {
    ...original,
    ...$json,
    message_to_send: message,
    message,
    db_operations: ["messages", "lead_state"],
    action: "reschedule_booking",
    outcome: stateUpdate.last_bot_action,
    decision,
    state_update: stateUpdate,
    execution_context: {
      ...(original.execution_context || {}),
      action: "reschedule_booking",
      state_update: stateUpdate,
      idempotency_key: null,
      inbound_message_id: null
    },
    idempotency_key: null,
    inbound_message_id: null,
    execution_result: {
      success: true,
      action: "reschedule_booking",
      outcome: stateUpdate.last_bot_action,
      bot: message,
      message_sent: false,
      state_updated: false,
      db_records_created: []
    },
    notes: [
      ...(original.notes || []),
      ...($json.notes || []),
      ...extraNotes
    ]
  };
}

if (slots.length === 0) {
  const stateUpdate = {
    ...(original.state_update || {}),
    stage: "reschedule",
    intent_last: "reschedule_no_available_slots",
    next_goal: "manual_availability_review",
    last_bot_action: "reschedule_no_slots_found",
    missing_fields: [],
    booking_options: []
  };

  const message =
    "Claro, podemos reprogramar, pero por ahora no encontre horarios disponibles para " +
    availabilityLabel +
    ". Te puedo ayudar a revisar otra alternativa.";

  return [buildCommonPayload(message, stateUpdate, ["reschedule_no_available_slots"])]
}

const lines = slots.map((slot, index) => String(index + 1) + ". " + formatSlot(slot));
const optionNumbers = slots.map((_, index) => index + 1).join(", ");

const stateUpdate = {
  ...(original.state_update || {}),
  stage: "reschedule",
  intent_last: "reschedule_requested",
  next_goal: "collect_selected_slot",
  last_bot_action: "offer_reschedule_slots",
  missing_fields: [],
  booking_date: null,
  booking_time: null,
  slot_id: null,
  availability_confirmed: false,
  booking_options: slots,
  availability_window: original.availability_window || $json.availability_window || "this_week",
  availability_label: availabilityLabel
};

const message =
  "Claro, podemos reprogramar. Tengo estos horarios disponibles para " +
  availabilityLabel +
  ":\n\n" +
  lines.join("\n") +
  "\n\n" +
  "Cual te acomoda? Puedes responder con " + optionNumbers + ".";

return [buildCommonPayload(message, stateUpdate, ["reschedule_slots_sent"])]

return [{
  ...$json,
  message_to_send:
    "Ese horario ya no esta disponible. Te puedo proponer otro horario para reprogramar.",
  db_operations: ["messages", "lead_state"],
  state_update: {
    ...($json.state_update || {}),
    stage: "reschedule",
    next_goal: "collect_new_slot",
    last_bot_action: "reschedule_slot_unavailable",
    availability_confirmed: false,
    missing_fields: []
  },
  notes: [
    ...($json.notes || []),
    "reschedule_slot_unavailable"
  ]
}];

const original = $("merge_slot_check_with_context").first().json;

return [{
  ...original,
  calendar_rescheduled: true,
  calendar_event_id:
    $json.id ||
    original.active_appointment?.event_id ||
    null,
  calendar_result: $json,
  notes: [
    ...(original.notes || []),
    "calendar_event_rescheduled"
  ]
}];

const original = $("normalize_calendar_reschedule_result").first().json;

return [{
  ...original,
  new_appointment: $json,
  notes: [
    ...(original.notes || []),
    "appointment_updated_after_reschedule"
  ]
}];

function serviceLabel(service) {
  const map = {
    lavado_basico: "lavado basico",
    lavado_premium: "lavado premium",
    encerado_full: "encerado full",
    lavado_profundo: "lavado premium",
    lavado_esencial: "lavado basico",
  };

  return map[service] || (service ? String(service).replace(/_/g, " ") : "el servicio");
}

function formatDateTime(value) {
  const start = new Date(value || Date.now());
  const fecha = start.toLocaleDateString("es-CL", {
    timeZone: "America/Santiago",
    day: "2-digit",
    month: "2-digit"
  });
  const hora = start.toLocaleTimeString("es-CL", {
    timeZone: "America/Santiago",
    hour: "2-digit",
    minute: "2-digit"
  });
  return { fecha, hora };
}

const service = serviceLabel($json.service_interest);
const when = formatDateTime($json.slot_start_at || $json.booking_date);

return [{
  ...$json,
  message_to_send: "Listo, tu " + service + " quedo reprogramado para el " + when.fecha + " a las " + when.hora,
  db_operations: ["appointments", "followups", "messages", "lead_state"],
  state_update: {
    ...($json.state_update || {}),
    stage: "booked",
    intent_last: "reschedule_confirmed",
    next_goal: "pre_service_reminder",
    last_bot_action: "reschedule_booking",
    booking_date: null,
    booking_time: null,
    slot_id: null,
    availability_confirmed: null,
    missing_fields: []
  },
  notes: [
    ...($json.notes || []),
    "booking_rescheduled"
  ]
}];

const original = (() => {
  try {
    return $("reschedule_booking").first().json;
  } catch {
    return {};
  }
})();

const mergedExecutionContext = {
  ...(original.execution_context || {}),
  ...($json.execution_context || {})
};

const data = {
  ...original,
  ...$json,
  execution_context: mergedExecutionContext,
  context_packet: $json.context_packet || original.context_packet || {},
  decision: $json.decision || original.decision || {}
};

const hasMessage = !!String(data.message_to_send || data.message || "").trim();
const hasBookingOptions = Array.isArray(data.state_update?.booking_options) && data.state_update.booking_options.length > 0;
const isSlotListResponse = hasMessage && hasBookingOptions;
const isSlotUnavailable = data.state_update?.last_bot_action === "reschedule_slot_unavailable";
const isNoActive = data.state_update?.last_bot_action === "reschedule_no_active_appointment";
const isSuccess = data.state_update?.last_bot_action === "reschedule_booking";

const outcome =
  isSlotListResponse ? "reschedule_slots_offered" :
  isSlotUnavailable ? "reschedule_slot_unavailable" :
  isNoActive ? "no_active_appointment" :
  isSuccess ? "reschedule_confirmed" :
  data.outcome ||
  data.execution_result?.outcome ||
  data.result?.outcome ||
  "reschedule_processed";

const finalMessage =
  data.message_to_send ||
  data.message ||
  (
    outcome === "no_active_appointment"
      ? "Revise y no encontre una reserva activa asociada a este numero. Si quieres, puedo ayudarte a agendar una nueva hora."
      : "Perfecto, te ayudo a reprogramar tu reserva. Te mostrare los horarios disponibles."
  );

const preservedStateUpdate = data.state_update || {};
const finalStateUpdate = {
  ...preservedStateUpdate,
  stage: preservedStateUpdate.stage || "reschedule",
  intent_last:
    preservedStateUpdate.intent_last ||
    (isSlotListResponse ? "reschedule_requested" : outcome),
  next_goal:
    preservedStateUpdate.next_goal ||
    (isNoActive ? "book_appointment" : isSlotListResponse ? "collect_selected_slot" : "show_available_slots"),
  last_bot_action:
    preservedStateUpdate.last_bot_action ||
    (isSlotListResponse ? "offer_reschedule_slots" : isNoActive ? "reschedule_no_active_appointment" : "reschedule_booking"),
  missing_fields: Array.isArray(preservedStateUpdate.missing_fields)
    ? preservedStateUpdate.missing_fields
    : []
};

const finalDecision = data.decision?.action
  ? {
      ...data.decision,
      state_update: {
        ...(data.decision.state_update || {}),
        ...finalStateUpdate
      }
    }
  : {
      action: "reschedule_booking",
      reason: outcome,
      source: "reschedule_booking",
      message: finalMessage,
      rule_name: "reschedule_booking_result",
      confidence: 1,
      state_update: finalStateUpdate,
      requires_message_builder: false
    };

return [{
  ...data,

  action: "reschedule_booking",
  outcome,

  message_to_send: finalMessage,
  message: finalMessage,

  db_operations: ["messages", "lead_state"],

  state_update: finalStateUpdate,
  decision: finalDecision,

  execution_context: {
    ...mergedExecutionContext,
    action: "reschedule_booking",
    state_update: finalStateUpdate,
    idempotency_key: null,
    inbound_message_id: null
  },
  idempotency_key: null,
  inbound_message_id: null,

  execution_result: {
    ...(data.execution_result || {}),
    success: true,
    action: "reschedule_booking",
    outcome,
    bot: finalMessage,
    message_sent: false,
    state_updated: false,
    db_records_created: []
  },

  notes: [
    ...(data.notes || []),
    `reschedule_booking_outcome_${outcome}`
  ]
}];

const original = $("merge_slot_check_with_context").first().json;
const auth = $json || {};

return [{
  json: {
    ...original,
    oauth_connected: auth.connected === true,
    oauth_access_token: auth.access_token || null,
    oauth_calendar_id: auth.calendar_id || null
  }
}];
